P["95dc9bb0-6487-4305-bd16-5d811a6ac328"] = [  # header definition linker error
    "Each .c file is compiled separately into an object file; #include pastes the header text in, so both objects contain a definition of the function.",
    "The linker then sees two external definitions of the same symbol and reports a multiple-definition error (one-definition rule).",
    "Fix: put only the declaration (prototype) in the header and the single definition in one .c file.",
    "Header guards stop a header being included twice in one translation unit (redefinition of types), but do not help across separate translation units.",
    "static on the definition gives each file its own private copy (internal linkage): it links, but duplicates code.",
    "static inline (or C99 inline with one extern definition) is the idiom for small functions meant to live in headers.",
]
